import{c as o,S as r,j as a,m as t}from"./chunks/framework.DjygN48H.js";const p=JSON.parse('{"title":"Architecture of Source Academy","description":"","frontmatter":{},"headers":[],"relativePath":"developer/architecture/index.md","filePath":"developer/architecture/index.md"}'),n={name:"developer/architecture/index.md"},i={viewBox:"0 0 760 440",role:"img","aria-labelledby":"arch-title arch-desc",style:{width:"100%",height:"auto","font-family":"var(--vp-font-family-base)","font-size":"13px"}};function s(d,e,c,h,l,u){return r(),a("div",null,[e[1]||(e[1]=t('<h1 id="architecture-of-source-academy" tabindex="-1">Architecture of Source Academy <a class="header-anchor" href="#architecture-of-source-academy" aria-label="Permalink to “Architecture of Source Academy”">​</a></h1><p>How the parts of Source Academy fit together, and which repository holds each. This page is the overview; the pages for the components are listed at the end.</p><p>Written on 28 November 2026 from the code and the READMEs of the repositories. Each page names the files it was checked against, so that a maintainer can tell what to update when the code changes.</p><h2 id="the-picture" tabindex="-1">The picture <a class="header-anchor" href="#the-picture" aria-label="Permalink to “The picture”">​</a></h2><p>A learner&#39;s browser runs the <strong>frontend</strong>. The frontend knows no language and no tool: it reads three <strong>directories</strong> (static JSON files on GitHub Pages) to find out which languages, evaluators, plugins and modules exist, and loads what it needs when a program runs. A language <strong>evaluator</strong> runs in a Web Worker and talks to the frontend through the <strong>Conductor</strong> protocol. Tools that show a program&#39;s execution, such as the Stepper, are <strong>plugins</strong> that the evaluator asks the frontend to load. The <strong>backend</strong> keeps the accounts, courses, assessments and submissions, and sends submissions to the <strong>grader</strong>, which runs the same evaluators on the server.</p>',5)),(r(),a("svg",i,[...e[0]||(e[0]=[t('<title id="arch-title">The parts of Source Academy and how they connect</title><desc id="arch-desc">The frontend in the browser loads evaluators and plugins named by three directories, runs an evaluator in a Web Worker over Conductor, and talks to the backend, which sends submissions to the grader.</desc><defs><marker id="arch-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10 z" fill="var(--vp-c-text-3)"></path></marker></defs><rect x="10" y="10" width="470" height="305" rx="10" fill="none" stroke="var(--vp-c-divider)" stroke-dasharray="5 4"></rect><text x="24" y="304" fill="var(--vp-c-text-2)">The learner&#39;s browser</text><rect x="30" y="60" width="200" height="90" rx="8" fill="var(--vp-c-bg-soft)" stroke="var(--vp-c-brand-1)" stroke-width="2"></rect><text x="130.0" y="90" text-anchor="middle" fill="var(--vp-c-text-1)" font-weight="600">Frontend</text><text x="130.0" y="112" text-anchor="middle" fill="var(--vp-c-text-2)">workspaces, editor, tabs</text><rect x="270" y="60" width="190" height="90" rx="8" fill="var(--vp-c-bg-soft)" stroke="var(--vp-c-divider)" stroke-width="2"></rect><text x="365.0" y="90" text-anchor="middle" fill="var(--vp-c-text-1)" font-weight="600">Evaluator</text><text x="365.0" y="112" text-anchor="middle" fill="var(--vp-c-text-2)">in a Web Worker</text><text x="365.0" y="130" text-anchor="middle" fill="var(--vp-c-text-2)">js-slang, py-slang, ...</text><rect x="30" y="195" width="200" height="80" rx="8" fill="var(--vp-c-bg-soft)" stroke="var(--vp-c-divider)" stroke-width="2"></rect><text x="130.0" y="225" text-anchor="middle" fill="var(--vp-c-text-1)" font-weight="600">Plugins</text><text x="130.0" y="247" text-anchor="middle" fill="var(--vp-c-text-2)">Stepper, E-Stepper,</text><text x="130.0" y="265" text-anchor="middle" fill="var(--vp-c-text-2)">Data Visualizer, CSE machine</text><rect x="270" y="195" width="190" height="80" rx="8" fill="var(--vp-c-bg-soft)" stroke="var(--vp-c-divider)" stroke-width="2"></rect><text x="365.0" y="225" text-anchor="middle" fill="var(--vp-c-text-1)" font-weight="600">Modules</text><text x="365.0" y="247" text-anchor="middle" fill="var(--vp-c-text-2)">bundles and tabs</text><text x="365.0" y="265" text-anchor="middle" fill="var(--vp-c-text-2)">that programs import</text><line x1="232" y1="105" x2="268" y2="105" stroke="var(--vp-c-text-3)" stroke-width="1.5" marker-start="url(#arch-arrow)" marker-end="url(#arch-arrow)"></line><text x="250" y="56" text-anchor="middle" fill="var(--vp-c-text-2)" font-size="11">Conductor</text><line x1="130" y1="152" x2="130" y2="193" stroke="var(--vp-c-text-3)" stroke-width="1.5" marker-end="url(#arch-arrow)"></line><text x="138" y="176" text-anchor="start" fill="var(--vp-c-text-2)" font-size="11">loads plugins, shows tabs</text><line x1="365" y1="152" x2="365" y2="193" stroke="var(--vp-c-text-3)" stroke-width="1.5" marker-end="url(#arch-arrow)"></line><text x="373" y="176" text-anchor="start" fill="var(--vp-c-text-2)" font-size="11">import</text><rect x="500" y="60" width="250" height="215" rx="10" fill="none" stroke="var(--vp-c-divider)" stroke-dasharray="5 4"></rect><text x="514" y="82" fill="var(--vp-c-text-2)">Static JSON on GitHub Pages</text><rect x="520" y="96" width="210" height="46" rx="8" fill="var(--vp-c-bg-soft)" stroke="var(--vp-c-divider)" stroke-width="2"></rect><text x="625" y="124" text-anchor="middle" fill="var(--vp-c-text-1)">Language directory</text><rect x="520" y="152" width="210" height="46" rx="8" fill="var(--vp-c-bg-soft)" stroke="var(--vp-c-divider)" stroke-width="2"></rect><text x="625" y="180" text-anchor="middle" fill="var(--vp-c-text-1)">Plugin directory</text><rect x="520" y="208" width="210" height="46" rx="8" fill="var(--vp-c-bg-soft)" stroke="var(--vp-c-divider)" stroke-width="2"></rect><text x="625" y="236" text-anchor="middle" fill="var(--vp-c-text-1)">Modules directory</text><path d="M 500 70 L 490 70 L 490 34 L 130 34 L 130 58" fill="none" stroke="var(--vp-c-text-3)" stroke-width="1.5" stroke-dasharray="4 3" marker-end="url(#arch-arrow)"></path><text x="310" y="28" text-anchor="middle" fill="var(--vp-c-text-2)" font-size="11">the frontend reads the directories at run time</text><rect x="30" y="350" width="170" height="80" rx="8" fill="var(--vp-c-bg-soft)" stroke="var(--vp-c-brand-1)" stroke-width="2"></rect><text x="115.0" y="380" text-anchor="middle" fill="var(--vp-c-text-1)" font-weight="600">Backend</text><text x="115.0" y="402" text-anchor="middle" fill="var(--vp-c-text-2)">Phoenix, PostgreSQL</text><rect x="290" y="350" width="170" height="80" rx="8" fill="var(--vp-c-bg-soft)" stroke="var(--vp-c-brand-1)" stroke-width="2"></rect><text x="375.0" y="380" text-anchor="middle" fill="var(--vp-c-text-1)" font-weight="600">Grader</text><text x="375.0" y="402" text-anchor="middle" fill="var(--vp-c-text-2)">AWS Lambda,</text><text x="375.0" y="420" text-anchor="middle" fill="var(--vp-c-text-2)">vendored evaluators</text><path d="M 30 105 L 20 105 L 20 390 L 28 390" fill="none" stroke="var(--vp-c-text-3)" stroke-width="1.5" marker-end="url(#arch-arrow)"></path><text x="36" y="338" text-anchor="start" fill="var(--vp-c-text-2)" font-size="11">HTTPS API</text><line x1="202" y1="390" x2="288" y2="390" stroke="var(--vp-c-text-3)" stroke-width="1.5" marker-end="url(#arch-arrow)"></line><text x="245" y="382" text-anchor="middle" fill="var(--vp-c-text-2)" font-size="11">submission</text>',47)])])),e[2]||(e[2]=t('<h2 id="the-parts-and-where-they-live" tabindex="-1">The parts, and where they live <a class="header-anchor" href="#the-parts-and-where-they-live" aria-label="Permalink to “The parts, and where they live”">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>What it is</th><th>Repository</th></tr></thead><tbody><tr><td><a href="./frontend">Frontend</a></td><td>The web application: workspaces, the editor, the side-content tabs, assessments, grading screens</td><td><a href="https://github.com/source-academy/frontend" target="_blank" rel="noreferrer"><code>frontend</code></a></td></tr><tr><td><a href="./backend">Backend</a></td><td>Accounts, courses, assessments, submissions, the API; Elixir, Phoenix, PostgreSQL</td><td><a href="https://github.com/source-academy/backend" target="_blank" rel="noreferrer"><code>backend</code></a></td></tr><tr><td><a href="./grader">Grader</a></td><td>Runs a submission&#39;s test cases in an evaluator, on AWS Lambda</td><td><a href="https://github.com/source-academy/grader" target="_blank" rel="noreferrer"><code>grader</code></a></td></tr><tr><td><a href="./directories">Directories</a></td><td>JSON lists of the languages and evaluators, of the plugins, and of the modules</td><td><a href="https://github.com/source-academy/language-directory" target="_blank" rel="noreferrer"><code>language-directory</code></a>, <a href="https://github.com/source-academy/plugin-directory" target="_blank" rel="noreferrer"><code>plugin-directory</code></a>, <a href="https://github.com/source-academy/modules" target="_blank" rel="noreferrer"><code>modules</code></a></td></tr><tr><td><a href="./conductor">Conductor</a></td><td>The protocol between a host and a runner, and the code that implements it</td><td><a href="https://github.com/source-academy/conductor" target="_blank" rel="noreferrer"><code>conductor</code></a></td></tr><tr><td><a href="./evaluators">Evaluators</a></td><td>One implementation per language</td><td><a href="https://github.com/source-academy/js-slang" target="_blank" rel="noreferrer"><code>js-slang</code></a>, <a href="https://github.com/source-academy/py-slang" target="_blank" rel="noreferrer"><code>py-slang</code></a>, <a href="https://github.com/source-academy/scm-slang" target="_blank" rel="noreferrer"><code>scm-slang</code></a>, <a href="https://github.com/source-academy/java-slang" target="_blank" rel="noreferrer"><code>java-slang</code></a>, <a href="https://github.com/source-academy/ocaml-slang" target="_blank" rel="noreferrer"><code>ocaml-slang</code></a></td></tr><tr><td><a href="./plugins-and-modules">Plugins and modules</a></td><td>Tools that show a run, and libraries that a program imports</td><td><a href="https://github.com/source-academy/plugins" target="_blank" rel="noreferrer"><code>plugins</code></a>, <a href="https://github.com/source-academy/modules" target="_blank" rel="noreferrer"><code>modules</code></a></td></tr><tr><td><a href="./deployment">Deployment</a></td><td>Where the parts run</td><td><a href="https://github.com/source-academy/backend" target="_blank" rel="noreferrer"><code>backend</code></a> (<code>deployment/</code>), GitHub Pages</td></tr></tbody></table><p>Two paths cross all of these: <a href="./run-and-submission">a run in the workspace, and a submission</a>.</p><h2 id="three-ideas-that-explain-most-of-the-design" tabindex="-1">Three ideas that explain most of the design <a class="header-anchor" href="#three-ideas-that-explain-most-of-the-design" aria-label="Permalink to “Three ideas that explain most of the design”">​</a></h2><ul><li><strong>The frontend knows no language and no tool.</strong> Which languages exist, which evaluator runs each, which tab shows what an evaluator computes: all of it is in the directories, and the frontend reads them at run time. A new language or tool is added to a directory, not to the frontend. (This is the direction the code is moving in; the frontend still contains a few special cases, tracked in <a href="https://github.com/source-academy/frontend/issues/4587" target="_blank" rel="noreferrer">frontend#4587</a>.)</li><li><strong>An evaluator is a program that speaks Conductor.</strong> It runs in a Web Worker in the browser and in a worker thread in the grader, with the same code in both.</li><li><strong>A tool is a plugin.</strong> The evaluator asks the host to load a plugin by its id in the plugin directory, and the plugin contributes a tab. <a href="./../writing-a-visualizer-plugin">Writing a visualizer plugin</a> describes how.</li></ul><h2 id="the-four-pieces-that-make-the-frontend-language-and-tool-agnostic" tabindex="-1">The four pieces that make the frontend language- and tool-agnostic <a class="header-anchor" href="#the-four-pieces-that-make-the-frontend-language-and-tool-agnostic" aria-label="Permalink to “The four pieces that make the frontend language- and tool-agnostic”">​</a></h2><h3 id="conductor" tabindex="-1">Conductor <a class="header-anchor" href="#conductor" aria-label="Permalink to “Conductor”">​</a></h3><p><a href="https://github.com/source-academy/conductor" target="_blank" rel="noreferrer"><code>conductor</code></a> is the standard interface between a <strong>host</strong> (an environment from which runners are created: the browser frontend, a command line, the grader) and a <strong>runner</strong> (the environment where user code runs, with an <strong>evaluator</strong> in it). Host and runner exchange messages over named, bidirectional <strong>channels</strong>; the standard ones carry results (<code>__result</code>), errors (<code>__error</code>), standard output (<code>__stdio</code>) and status (<code>__status</code>). A <strong>plugin</strong> is a program loaded on demand that can listen on and send over channels. An evaluator implements <code>IEvaluator</code> (the base class <code>BasicEvaluator</code> needs only <code>evaluateChunk</code>), and an entry point creates a <code>Conduit</code> and registers the runner plugin. Conductor also defines the <strong>module interface</strong>: the data types and the functions with which a module (a library such as <code>rune</code> or <code>plotly</code>) reads and builds values of an evaluator without knowing its memory model. More in <a href="./conductor">Conductor</a>.</p><h3 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to “Plugins”">​</a></h3><p>A <strong>plugin</strong> is how a tool joins a run. The Stepper, the E-Stepper, the Data Visualizer and the CSE machine are plugins: each has a package that the evaluator uses (<code>common-*</code> for the protocol, <code>runner-*</code> for the evaluator&#39;s side) and a package that the browser loads (<code>web-*</code>, which contributes a side-content tab). They live in <a href="https://github.com/source-academy/plugins" target="_blank" rel="noreferrer"><code>plugins</code></a>, are built into bundles on GitHub Pages, and are found through the plugin directory. An evaluator asks the host to load one with <code>hostLoadPlugin(id)</code>. More in <a href="./plugins-and-modules">Plugins and modules</a>, and <a href="./../writing-a-visualizer-plugin">Writing a visualizer plugin</a>.</p><h3 id="language-directory" tabindex="-1">Language directory <a class="header-anchor" href="#language-directory" aria-label="Permalink to “Language directory”">​</a></h3><p><a href="https://github.com/source-academy/language-directory" target="_blank" rel="noreferrer"><code>language-directory</code></a> lists the languages that Source Academy supports. A <strong>language definition</strong> has an id, a name, the <strong>evaluators</strong> that can run it, and optional settings: an editor configuration, a textbook (with the chapters written in this language), and links to documentation. An <strong>evaluator definition</strong> has an id, a name, the URL of the evaluator&#39;s entry file, its capabilities, and optionally the id of a <strong>plugin</strong> whose tab presents what the evaluator computes (an evaluator with that field is hidden from the evaluator dropdown, and chosen when the user opens the plugin&#39;s tab). The directory is published as JSON at <code>https://source-academy.github.io/language-directory/directory.json</code>; on 28 November 2026 it lists 13 languages (Python §1 to §4, Python §4 Typed, full Python, Source §1 to §4, Scheme, Java, OCaml). A new language is added to <code>src/languages.ts</code>. More in <a href="./directories">Directories</a>.</p><h3 id="plugin-directory" tabindex="-1">Plugin directory <a class="header-anchor" href="#plugin-directory" aria-label="Permalink to “Plugin directory”">​</a></h3><p><a href="https://github.com/source-academy/plugin-directory" target="_blank" rel="noreferrer"><code>plugin-directory</code></a> lists the plugins. A <strong>plugin definition</strong> has an id, a name, an optional description, an optional <code>tab</code> (its id, label, icon, and whether it hides the host&#39;s REPL or keeps the side content from being resized, so that the host can show a placeholder before the plugin loads), and <strong>resolutions</strong>: for each kind of environment (web, runner, module) the URL of the plugin&#39;s entry file. On 28 November 2026 it lists four plugins: <code>stepper</code>, <code>e-stepper</code>, <code>data-visualizer</code> and <code>cse-machine</code>. A new plugin is added to <code>src/plugins.ts</code>. More in <a href="./directories">Directories</a>.</p><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to “Pages”">​</a></h2><ul><li><a href="./frontend">Frontend</a></li><li><a href="./backend">Backend</a></li><li><a href="./grader">Grader</a></li><li><a href="./directories">Directories</a></li><li><a href="./conductor">Conductor</a></li><li><a href="./evaluators">Evaluators</a></li><li><a href="./plugins-and-modules">Plugins and modules</a></li><li><a href="./deployment">Deployment</a></li><li><a href="./run-and-submission">A run in the workspace, and a submission</a></li></ul>',16))])}const f=o(n,[["render",s]]);export{p as __pageData,f as default};
